const PREFIX='mockupbench-'+encodeURIComponent(self.registration.scope)+'-';
const CACHE=PREFIX+'1.6.0-rc.1';
const FILES=["./INTERFACEBENCH-LICENSE.txt","./README.md","./THIRD-PARTY.md","./app.js","./assemblies.js","./cinematic.js","./components.js","./dimensions.js","./drawing-format.js","./drawing-geometry.js","./drawing-options.js","./drawing-ui.js","./drawings.js","./enclosure-ui.js","./enclosure.js","./engineering-ui.js","./fabrication.js","./geometry.js","./harness.js","./icon.svg","./import-worker.js","./importers.js","./index.html","./interface-catalog.js","./model.js","./motion.js","./movie-ui.js","./movie.js","./mp4-worker.js","./placement-ui.js","./placement.js","./rendering.js","./review.js","./scene.js","./schema.js","./storage.js","./style.css","./surface-features.js","./transform-ui.js","./transforms.js","./ui.js","./vendor/BufferGeometryUtils.js","./vendor/DRAWING-FONT-LICENSE.txt","./vendor/FONT-LICENSE","./vendor/FONT-README.txt","./vendor/FontLoader.js","./vendor/GLTFExporter.js","./vendor/GLTFLoader.js","./vendor/H264-MP4-ENCODER-LICENSE.txt","./vendor/LIBMP4V2-LICENSE.txt","./vendor/MANIFOLD-LICENSE.txt","./vendor/MINIH264-LICENSE.txt","./vendor/OBB.js","./vendor/OrbitControls.js","./vendor/STLExporter.js","./vendor/STLLoader.js","./vendor/SVGLoader.js","./vendor/THREE-LICENSE.txt","./vendor/TransformControls.js","./vendor/drawing-font.js","./vendor/drawing-font.ttf","./vendor/fonts.js","./vendor/h264-mp4-encoder.web.js","./vendor/license.occt-import-js.txt","./vendor/license.occt.txt","./vendor/manifold.js","./vendor/manifold.wasm","./vendor/occt-import-js.js","./vendor/occt-import-js.wasm","./vendor/three.core.js","./vendor/three.module.js","./video-encoder.js","./workspace.js"];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES))));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith(PREFIX)&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==location.origin)return;event.respondWith(caches.match(event.request).then(cached=>cached||fetch(event.request).catch(error=>{if(event.request.mode==='navigate')return caches.match(new URL('./index.html',self.registration.scope));throw error;})));});
